#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;
vector<long long> memo;

long long ways(int n) {
    if (n <= 1) return 1;
    if (memo[n] != -1) return memo[n];
    return memo[n] = (ways(n - 1) + ways(n - 2)) % MOD;
}

int depth(int n) {
    if (n == 0) return 0;
    return depth(n - 1) + 1;
}

int main() {
    cout << depth(10000) << '\n';  // 깊이 1만은 보통 괜찮아요
    memo.assign(301, -1);
    cout << ways(300) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> dfs_order(int start, const vector<vector<int>> &adj) {
    int n = adj.size() - 1;
    vector<bool> visited(n + 1, false);
    vector<int> order, st = {start};
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        if (visited[u]) continue;
        visited[u] = true;
        order.push_back(u);
        for (int i = (int)adj[u].size() - 1; i >= 0; i--)  // 재귀와 같은 순서로 방문
            if (!visited[adj[u][i]]) st.push_back(adj[u][i]);
    }
    return order;
}

int main() {
    int n = 6;
    vector<vector<int>> adj(n + 1);
    int edges[5][2] = {{1, 2}, {1, 3}, {2, 4}, {2, 5}, {3, 6}};
    for (auto &e : edges) {
        adj[e[0]].push_back(e[1]);
        adj[e[1]].push_back(e[0]);
    }
    for (int x : dfs_order(1, adj)) cout << x << ' ';
    cout << '\n';

    int m = 1000000;  // 일자 그래프: 재귀라면 깊이 100만
    vector<vector<int>> chain(m + 1);
    for (int i = 1; i < m; i++) {
        chain[i].push_back(i + 1);
        chain[i + 1].push_back(i);
    }
    vector<int> order = dfs_order(1, chain);
    cout << order.size() << ' ' << order.back() << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int big[1000000];  // 전역: 스택을 쓰지 않아요(0 으로 초기화)

int main() {
    vector<long long> v(1000000);  // 데이터는 힙에 잡혀요
    for (int i = 0; i < 1000000; i++) {
        big[i] = i % 7;
        v[i] = i;
    }
    long long s1 = 0, s2 = 0;
    for (int i = 0; i < 1000000; i++) {
        s1 += big[i];
        s2 += v[i];
    }
    cout << s1 << ' ' << s2 << '\n';
    return 0;
}

